namespace Acme.Pricing;

public static class DiscountPolicy
{
    public static decimal For(decimal subtotal) => subtotal switch
    {
        >= 5000m => subtotal * 0.1m,
        >= 1000m => subtotal * 0.05m,
        _ => 0m,
    };
}

using Acme.Pricing;
using Xunit;

namespace Acme.Tests;

public class DiscountPolicyTests
{
    [Fact]
    public void NoDiscountBelowOneThousand()
    {
        Assert.Equal(0m, DiscountPolicy.For(999m));
    }

    [Fact]
    public void FivePercentFromOneThousand()
    {
        Assert.Equal(50m, DiscountPolicy.For(1000m));
    }

    [Fact]
    public void FivePercentJustBelowFiveThousand()
    {
        Assert.Equal(249.95m, DiscountPolicy.For(4999m));
    }

    [Fact]
    public void TenPercentFromFiveThousand()
    {
        Assert.Equal(500m, DiscountPolicy.For(5000m));
    }
}

